def topic(name,cn,terms=None):
    phrases=terms or [name]
    return dict(topic_id=name,name=name,aliases=[cn],positive_terms=[r'\b'+re.escape(p).replace(r'\ ',r'[ -]')+r'\b' for p in phrases]+[cn],negative_terms=[],queries=[name,cn],priority=1,target_count=30,importance=1,emergence=1,transfer_relevance=1)

def family(identity,cn,en,description,topics,sources,venues):
    core=[p for t in topics for p in t['positive_terms']]
    return dict(domain_id=identity,domain_name=cn,domain_name_cn=cn,domain_name_en=en,aliases=[en,identity],description=description,parent_domain=identity,topics=topics,query_terms_cn=[t['aliases'][0] for t in topics],query_terms_en=[t['name'] for t in topics],positive_terms=core,weak_terms=[],negative_terms=['primary school|education assessment|patient survival prediction'],negative_exceptions=[],context_terms=core,boundary_terms=[],preferred_sources=sources,search_sources=sources,preferred_venues=venues,year_policy={'priority_years':[2023,2024],'include_classics':True},target_years=list(range(2019,2027)),priority=1.3,target_depth=300,target_count=300,enabled=True,oa_resolvers=['openalex','semantic_scholar','arxiv','europe_pmc'],importance=1.4,emergence=1.2,transfer_relevance=1.5)

